+            </main>
+            <footer class="site-footer">
+              <p>Average first response: one business day.</p>
+            </footer>
+          </div>
+        `;
+      }
+
+      function attachFormHandlers() {
+        const form = document.querySelector("#support-form");
+
+        fields.forEach((field) => {
+          const input = document.querySelector(`#${field.id}-input`);
+          input.addEventListener("input", (event) => {
+            state.values[field.id] = event.target.value;
+            if (state.touched[field.id] || state.submitted) {
+              const error = validateField(field, state.values[field.id]);
+              if (error) {
+                state.errors[field.id] = error;
+              } else {
+                delete state.errors[field.id];
+              }
+              render();
+              document.querySelector(`#${field.id}-input`).focus();
+            }
+          });
+
+          input.addEventListener("blur", () => {
+            state.touched[field.id] = true;
+            const error = validateField(field, state.values[field.id]);
+            if (error) {
+              state.errors[field.id] = error;
+            } else {
+              delete state.errors[field.id];
+            }
+            render();
+          });
+        });
+
+        form.addEventListener("submit", (event) => {
+          event.preventDefault();
+          state.submitted = true;
+          state.touched = fields.reduce((touched, field) => {
+            touched[field.id] = true;
+            return touched;
+          }, {});
+          state.errors = validateForm();
+          render();
+
+          const firstInvalidField = fields.find((field) => state.errors[field.id]);
+          if (firstInvalidField) {
+            document.querySelector(`#${firstInvalidField.id}-input`).focus();
+          } else {
